import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import {
  EmployeeOption,
  HrQualificationDto,
  QualificationSavePayload,
  QualificationSearchParams,
} from './manage-qualification-info.model';

const API_BASE = '/hrm/empinfo/api/qualification';

/**
 * Gọi lại nguyên các API JSON đã có sẵn ở HrEmpinfoController (không đổi backend) - xem giải thích ở
 * ManageQualificationInfoComponent. searchEmployees dùng chung endpoint sẵn có của toàn hệ thống
 * (giống PunishmentInfoService/FamilyInfoService...).
 */
@Injectable({ providedIn: 'root' })
export class ManageQualificationInfoService {
  constructor(private readonly http: HttpClient) {}

  search(params: QualificationSearchParams): Observable<HrQualificationDto[]> {
    let httpParams = new HttpParams();
    if (params.empId) httpParams = httpParams.set('empId', params.empId);
    if (params.localName) httpParams = httpParams.set('localName', params.localName);
    if (params.qualName) httpParams = httpParams.set('qualName', params.qualName);
    return this.http.get<HrQualificationDto[]>(API_BASE, { params: httpParams, withCredentials: true });
  }

  save(payload: QualificationSavePayload): Observable<{ message: string }> {
    return this.http.post<{ message: string }>(`${API_BASE}/save`, payload, { withCredentials: true });
  }

  delete(qualNo: number): Observable<{ message: string }> {
    return this.http.delete<{ message: string }>(`${API_BASE}/delete/${qualNo}`, { withCredentials: true });
  }

  searchEmployees(keyword: string): Observable<EmployeeOption[]> {
    let params = new HttpParams();
    if (keyword) params = params.set('keyword', keyword);
    return this.http.get<EmployeeOption[]>('/hrm/empinfo/api/employee/search', { params, withCredentials: true });
  }
}
